const db = new Database('/workspace/world.db');

const customerId = 'user_d3d5d0c8';
const productId = 'PROD-FA0948';
const cartId = 'CART-' + customerId;

// 1. Get the product
const product = db.prepare('SELECT * FROM products WHERE product_id = ?').get(productId);
console.log('Product:', product.name, '- Price:', product.price, '- In Stock:', product.in_stock, '- Stock Qty:', product.stock_quantity);

// 2. Get current cart
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);
const itemIds = JSON.parse(cart.item_ids_json);
console.log('Current cart items:', itemIds);

// 3. Check if product already in cart
const existingItem = db.prepare('SELECT * FROM cart_items WHERE customer_id = ? AND product_id = ?').get(customerId, productId);
console.log('Existing item in cart:', existingItem ? existingItem.cart_item_id : 'none');

// 4. Find next CI sequence
const maxCi = db.prepare(\"SELECT cart_item_id FROM cart_items ORDER BY cart_item_id DESC LIMIT 1\").get();
console.log('Max existing CI:', maxCi ? maxCi.cart_item_id : 'none');

// Determine next CI number
const allCis = db.prepare('SELECT cart_item_id FROM cart_items').all();
let maxSeq = 0;
allCis.forEach(ci => {
  const m = ci.cart_item_id.match(/^CI-(\d+)$/);
  if (m) maxSeq = Math.max(maxSeq, parseInt(m[1]));
});
const nextCiId = 'CI-' + String(maxSeq + 1).padStart(4, '0');
console.log('Next CI ID:', nextCiId);

// 5. Insert new cart item
db.prepare('INSERT INTO cart_items (cart_item_id, cart_id, customer_id, product_id, quantity, gift_wrap, variant_id) VALUES (?,?,?,?,?,?,?)').run(
  nextCiId, cartId, customerId, productId, 1, 0, null
);

// 6. Update cart: add item_id, recompute subtotal and total
itemIds.push(nextCiId);

// Get all cart items to recompute
const allCartItems = db.prepare('SELECT ci.*, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.customer_id = ?').all(customerId);
let subtotal = 0;
let giftWrapCount = 0;
allCartItems.forEach(ci => {
  subtotal += ci.price * ci.quantity;
  if (ci.gift_wrap) giftWrapCount++;
});
const giftWrapFee = giftWrapCount * 5; // $5 per gift-wrapped item
const discountAmount = cart.discount_amount;
const loyaltyDiscount = cart.loyalty_discount;
const shippingCost = cart.shipping_cost;
const total = Math.max(0, subtotal + giftWrapFee + shippingCost - discountAmount - loyaltyDiscount);

