console.log('Gift wrap fee:', giftWrapFee);
console.log('Shipping cost:', shippingCost);
console.log('Discount:', discountAmount);
console.log('New total:', total);

// 7. Update the cart record
db.prepare('UPDATE carts SET subtotal=?, gift_wrap_fee=?, total=?, item_ids_json=? WHERE cart_id=?').run(
  subtotal, giftWrapFee, total, JSON.stringify(itemIds), cartId
);

// 8. Verify
const updatedCart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);
const updatedItems = db.prepare('SELECT ci.*, p.name, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.customer_id = ?').all(customerId);

console.log('\n=== UPDATED CART ===');
console.log(JSON.stringify(updatedCart, null, 2));
console.log('\n=== ALL CART ITEMS ===');
updatedItems.forEach(ci => {
  console.log(ci.cart_item_id, '-', ci.name, '- Qty:', ci.quantity, '- Price: $' + ci.price, '- Gift Wrap:', ci.gift_wrap ? 'Yes' : 'No');
});
